/**
 * The pdf.js worker, with the one method an older phone is missing.
 *
 * WHY THIS FILE EXISTS. `pdf.worker.min.mjs` calls `Promise.withResolvers()`,
 * which iOS Safari only grew in 17.4. A worker is its own JavaScript realm, so
 * the shim `site/erp-ocr.js` installs on the page cannot reach it — the worker
 * would still die on a phone a year behind, and it would die out of sight,
 * because a worker's exception surfaces as "the document could not be read"
 * rather than as itself.
 *
 * WHY NOT EDIT THE VENDORED FILE. `site/vendor/MANIFEST.json` says its
 * contents are generated by `tools/vendor-ocr.mjs`. A polyfill written into
 * `pdf.worker.min.mjs` would be erased by the next vendoring run, and erased
 * silently — the reader would simply start failing again on the phones it was
 * fixed for. A wrapper we own cannot be overwritten by a tool that does not
 * know about it.
 *
 * THE DYNAMIC IMPORT IS THE POINT, not a style choice. A static `import` is
 * hoisted and evaluated BEFORE any statement in this file, so the real worker
 * would run first and the shim would arrive too late to be of any use. The
 * await keeps the module's evaluation — and therefore the worker's readiness —
 * suspended until the real worker has been evaluated, so no message is
 * delivered to a worker that is not listening yet.
 */
if (typeof Promise.withResolvers !== "function") {
  Promise.withResolvers = function withResolvers() {
    let resolve;
    let reject;
    const promise = new Promise((res, rej) => {
      resolve = res;
      reject = rej;
    });
    return { promise, resolve, reject };
  };
}

await import("./vendor/pdfjs/pdf.worker.min.mjs");
